actions.script:
const out = ec.service.sync().name('org.moqui.ui.NotificationServices.get#WebPushStatus')
        .parameters({endpoint: ec.web.parameters.endpoint || null}).disableAuthz().call() || {}
ec.web.sendJsonResponse({supported: !!out.supported, configured: !!out.configured, publicKey: out.publicKey || '',
    subscribed: !!out.subscribed, signedIn: !!ec.user.userId})

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const parameters = ec.web.parameters
    const out = ec.service.sync().name('org.moqui.ui.NotificationServices.store#WebPushSubscription')
            .parameters({endpoint: parameters.endpoint, p256dhKey: parameters.p256dhKey,
                authSecret: parameters.authSecret, userAgent: ec.web.request?.getHeader?.('User-Agent') || null})
            .disableAuthz().call()
    if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(400, errors) }
    else ec.web.sendJsonResponse({subscribed: true})
}

if (ec.user.userId && ec.web.parameters.endpoint) {
    ec.service.sync().name('org.moqui.ui.NotificationServices.delete#WebPushSubscription')
            .parameters({endpoint: ec.web.parameters.endpoint}).disableAuthz().call()
}
if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(400, errors) }
else ec.web.sendJsonResponse({subscribed: false})
